function each<T>(rows: T[]) {
  return (title: (row: T, index: number) => string, fn: (...args: any[]) => void) => {
    rows.forEach((row, index) => {
      const args: any[] = Array.isArray(row) ? row : [row];
      it(title(row, index), () => fn(...args));
    });
  };
}

