const VARIANTS: Array<[boolean, boolean]> = [
  [false, false],
  [true, false],
  [false, true],
  [true, true],
];

describe("url.parse", () => {
  each(PARSE)(
    ([input]) => `parses ${label(input)}`,
    (input: string, expected: string[]) => {
      VARIANTS.forEach(([parseQueryString, slashesDenoteHost], variant) => {
        let want = expected[variant];
        if (want.startsWith("=")) want = expected[Number(want.slice(1))];
        const got = outcome(() => digest(serialize(parse(input, parseQueryString, slashesDenoteHost))));
        expect(got).toBe(want);
      });
    }
  );

  it("returns Url instances whose fields are the parse result", () => {
    const parsed = parse("http://user:pass@host.com:8080/p/a/t/h?query=string#hash");
    expect(parsed).toBeInstanceOf(Url);
    expect(Object.keys(parsed)).toEqual([
      "protocol",
      "slashes",
      "auth",
      "host",
      "port",
      "hostname",
      "hash",
      "search",
      "query",
      "pathname",
      "path",
      "href",
    ]);
    expect(parsed.auth).toBe("user:pass");
    expect(parsed.port).toBe("8080");
  });

  it("returns a Url argument unchanged", () => {
    const parsed = parse("http://a/b");
    expect(parse(parsed as any)).toBe(parsed);
  });

  it("gives parseQueryString a null-prototype query even without a search", () => {
    const parsed = parse("http://example.com", true);
    expect(Object.getPrototypeOf(parsed.query)).toBeNull();
    expect(parsed.search).toBeNull();
    expect(parse("/p?a=1&a=2&b=%20c", true).query).toEqual({ a: ["1", "2"], b: " c" });
  });

  each([[undefined], [null], [1], [{}], [[]], [new URL("http://a/b")]])(
    ([value]) => `rejects ${String(value && (value as any).constructor?.name) || String(value)}`,
    (value: unknown) => {
      let error: any;
      try {
        parse(value as any);
      } catch (e) {
        error = e;
      }
      expect(error?.code).toBe("ERR_INVALID_ARG_TYPE");
      expect(error?.message).toContain('The "url" argument must be of type string. Received');
    }
  );

  it("rejects a missing argument", () => {
    expect(() => (parse as any)()).toThrow(/The "url" argument must be of type string/);
  });
});

describe("url.Url", () => {
  it("starts with every field null, in order", () => {
    const u: any = new Url();
    expect(Object.keys(u)).toEqual([
      "protocol",
      "slashes",
      "auth",
      "host",
      "port",
      "hostname",
      "hash",
      "search",
      "query",
      "pathname",
      "path",
      "href",
    ]);
    for (const key of Object.keys(u)) expect(u[key]).toBeNull();
  });

  it("is a named constructor with the same prototype methods as Node", () => {
    expect(typeof Url).toBe("function");
    expect(Url.name).toBe("Url");
    expect(Url.length).toBe(0);
    expect(Object.getOwnPropertyNames(Url.prototype).sort()).toEqual(
      ["constructor", "format", "parse", "parseHost", "resolve", "resolveObject"].sort()
    );
    expect(urlModule.Url).toBe(Url);
  });

  it("parse, resolve and format work as methods", () => {
    const u = new Url();
    expect(u.parse("http://x:1/y?z", true)).toBe(u);
    expect(u.port).toBe("1");
    expect((u.query as any).z).toBe("");
    expect(u.format()).toBe("http://x:1/y?z");
    expect(new Url().parse("http://x/y").resolve("z")).toBe("http://x/z");
  });

  it("is not a URL", () => {
    expect(parse("http://a/") instanceof URL).toBe(false);
  });
});

describe("url.resolve / url.resolveObject", () => {
  each(RESOLVE)(
    ([from, to]) => `${JSON.stringify(from)} + ${JSON.stringify(to)}`,
    (from: string, to: string, resolved: string, resolvedObject: string) => {
      expect(outcome(() => JSON.stringify(resolve(from, to)))).toBe(resolved);
      expect(outcome(() => serialize(resolveObject(from, to)))).toBe(resolvedObject);
    }
  );

  it("resolveObject returns the relative part when the source is empty", () => {
    expect(resolveObject("", "x")).toBe("x");
  });

  it("resolveObject accepts a Url as the relative part", () => {
    const resolved: any = resolveObject("http://a/b", parse("../c"));
    expect(resolved).toBeInstanceOf(Url);
    expect(resolved.href).toBe("http://a/c");
  });

  it("resolve rejects non-strings", () => {
    for (const args of [[1, "a"], ["a", 1], ["a"]]) {
      let error: any;
      try {
        (resolve as any)(...args);
      } catch (e) {
        error = e;
      }
      expect(error?.code).toBe("ERR_INVALID_ARG_TYPE");
    }
  });
});

describe("url.format", () => {
  each(FORMAT_STRINGS)(
    ([input]) => `formats the string ${JSON.stringify(input)}`,
    (input: string, expected: string) => {
      expect(outcome(() => JSON.stringify(format(input)))).toBe(expected);
    }
  );

  each(FORMAT_OBJECTS)(
    ([input]) => `formats the object ${JSON.stringify(input)}`,
    (input: Record<string, unknown>, expected: string) => {
      expect(outcome(() => JSON.stringify(format(input as any)))).toBe(expected);
    }
  );

  it("honours the WHATWG URL options", () => {
    expect(format(new URL("http://u:p@x.com/p?q#h"), { fragment: false, auth: false })).toBe("http://x.com/p?q");
    expect(format(new URL("mailto:a@b"))).toBe("mailto:a@b");
    expect(format(new URL("file:///a/b?q#h"), { search: false })).toBe("file:///a/b#h");
    expect(format(new URL("http://xn--mnchen-3ya.de/"), { unicode: true })).toBe("http://m\u00fcnchen.de/");
    expect(format(new URL("http://u:p@x.com:81/p?q#h"))).toBe("http://u:p@x.com:81/p?q#h");
  });

  it("rejects non-object, non-string input", () => {
    for (const value of [undefined, null, 1]) {
      let error: any;
      try {
        format(value as any);
      } catch (e) {
        error = e;
      }
      expect(error?.code).toBe("ERR_INVALID_ARG_TYPE");
      expect(error?.message).toContain('The "urlObject" argument must be one of type object or string. Received');
    }
  });
});

describe("url.fileURLToPathBuffer", () => {
  each(FILE_URL_TO_PATH_BUFFER)(
    ([input, options]) => `${JSON.stringify(input)}${options ? " (windows)" : ""}`,
    (input: string, options: { windows: boolean } | undefined, expected: string) => {
      const got = outcome(() => {
        const result = fileURLToPathBuffer(input, options);
        return Buffer.isBuffer(result) ? result.toString("hex") : "NOTBUF";
      });
      expect(got).toBe(expected);
    }
  );

  it("accepts URL objects and returns the raw decoded bytes", () => {
    const result = fileURLToPathBuffer(new URL("file:///a/b%20c"));
    expect(Buffer.isBuffer(result)).toBe(true);
    expect(result.toString("hex")).toBe("2f612f622063");
    expect([...fileURLToPathBuffer("file:///%FF%FE")]).toEqual([0x2f, 0xff, 0xfe]);
  });

  it("does not forbid encoded separators, unlike fileURLToPath", () => {
    expect(fileURLToPathBuffer("file:///a%2Fb").toString()).toBe("/a/b");
  });

  it("treats null and undefined options as the platform default", () => {
    expect(fileURLToPathBuffer("file:///a/b", undefined).toString()).toBe("/a/b");
    expect(fileURLToPathBuffer("file:///a/b", null as any).toString()).toBe("/a/b");
    expect(fileURLToPathBuffer("file:///a/b", { windows: false }).toString()).toBe("/a/b");
  });

  it("rejects non-file URLs and non-URL arguments", () => {
    const failure = (fn: () => unknown): any => {
      try {
        fn();
      } catch (e) {
        return e;
      }
    };
    expect(failure(() => fileURLToPathBuffer("http://x/y")).code).toBe("ERR_INVALID_URL_SCHEME");
    expect(failure(() => fileURLToPathBuffer("/not/url")).code).toBe("ERR_INVALID_URL");
    for (const value of [undefined, 1, null, Buffer.from("x"), { href: "file:///x" }]) {
      const error = failure(() => fileURLToPathBuffer(value as any));
      expect(error.code).toBe("ERR_INVALID_ARG_TYPE");
      expect(error.message).toContain('The "path" argument must be of type string or an instance of URL. Received');
    }
    expect(failure(() => (fileURLToPathBuffer as any)()).code).toBe("ERR_INVALID_ARG_TYPE");
  });

  it("has Node's arity", () => {
    expect(fileURLToPathBuffer.length).toBe(1);
    expect(fileURLToPathBuffer.name).toBe("fileURLToPathBuffer");
  });
});
